def task_func(myString, API_KEY):
    url_pattern = r'https?://[^\s<>"\'{}|\\^`\[\]]+'
    urls = re.findall(url_pattern, myString)
    domains = set()
    for url in urls:
        parsed = urllib.parse.urlparse(url)
        domain = parsed.netloc
        if domain:
            domains.add(domain)
    result = {}
    for domain in domains:
        try:
            response = requests.get(f'http://ip-api.com/json/{domain}?api_key={API_KEY}', timeout=5)
            if response.status_code == 200:
                result[domain] = response.json()
            else:
                result[domain] = None
        except:
            result[domain] = None
    return result
```

