1. Parse the JSON string into a Python dictionary.
2. Recursively traverse the dictionary to extract all string values.
3. Use a regex pattern to find all URLs in those strings.
4. Count the occurrences of each URL using Counter.
5. Return the dictionary of URL counts.

### code
```python
import re
import json
from collections import Counter

def task_func(json_str, top_n=10):
    try:
        data = json.loads(json_str)
    except json.JSONDecodeError:
        return {}

    def extract_strings(obj, strings):
        if isinstance(obj, str):
            strings.append(obj)
        elif isinstance(obj, dict):
            for v in obj.values():
                extract_strings(v, strings)
        elif isinstance(obj, list):
            for item in obj:
                extract_strings(item, strings)

    all_strings = []
    extract_strings(data, all_strings)

    url_pattern = re.compile(r'https?://[^\s"\'<>]+')
    urls = []
    for s in all_strings:
        urls.extend(url_pattern.findall(s))

    return dict(Counter(urls))
```

