1. Check if the file exists at the given path; if not, raise a ValueError.
2. Load the JSON file and parse it into a Python object.
3. Validate that all required fields from the schema are present in the JSON object; if missing, raise a ValueError.
4. For each required field, check that its actual type matches the type defined in the schema; if not, raise a ValueError.
5. For the email field, apply the provided regular expression to validate its format; if invalid, raise a ValueError.
6. Return the value of the specified attribute from the JSON object.
### code
```python
import json
import os
import re
def task_func(
    file_path,
    attribute,
    INPUT_JSON={
        "type": "object",
        "properties": {
            "name": {"type": str},  
            "age": {"type": int},   
            "email": {"type": str}  
        },
        "required": ["name", "age", "email"]
    },
    EMAIL_REGEX=r"^[a-z0-9]+[\._]?[a-z0-9]+[@]\w+[.]\w{2,3}$"):
    if not os.path.exists(file_path):
        raise ValueError("File does not exist")
    with open(file_path, 'r') as f:
        data = json.load(f)
    for req in INPUT_JSON["required"]:
        if req not in data:
            raise ValueError(f"Missing required attribute: {req}")
        expected_type = INPUT_JSON["properties"][req]["type"]
        if not isinstance(data[req], expected_type):
            raise ValueError(f"Type mismatch for attribute {req}: expected {expected_type}, got {type(data[req])}")
    if "email" in data:
        if not re.match(EMAIL_REGEX, data["email"]):
            raise ValueError("Invalid email format")
    return data.get(attribute)
```

